package com.sanser.mobile
import org.junit.Assert.*
import org.junit.Test

class RelayCipherTest {
    private val session="11111111-1111-4111-8111-111111111111"
    private val own="22222222-2222-4222-8222-222222222222"
    private val peer="33333333-3333-4333-8333-333333333333"
    private val token="mobile-test-credential-01234567890123456789"
    private fun unhex(hex:String)=hex.chunked(2).map{it.toInt(16).toByte()}.toByteArray()
    // Generated by the pinned libsodium backend used by iOS. This independently
    // checks Tink's nonce, tag, UUID encoding, key domain and associated data.
    private val fixture=unhex("534e523133333333333343338333333333333333000102030405060708090a0b0c0d0e0f0000000000000007571a15de536de063629f87dc310ab4abc326d0684f0921388b0abfef6b7b2888a8299a93fd0425f5e3")
    @Test fun opensLibsodiumFixtureAndRejectsReplay(){
        val cipher=RelayCipher(session,own,peer,token)
        assertEquals("authenticated-mobile-test",cipher.open(fixture)?.toString(Charsets.UTF_8))
        assertNull(cipher.open(fixture))
    }
    @Test fun tamperDoesNotPoisonReplayWindow(){
        val cipher=RelayCipher(session,own,peer,token)
        val corrupt=fixture.copyOf();corrupt[corrupt.lastIndex]=(corrupt.last().toInt() xor 1).toByte()
        assertNull(cipher.open(corrupt));assertNotNull(cipher.open(fixture))
        assertNull(RelayCipher(session,own,peer,token+"wrong").open(fixture))
        assertNull(RelayCipher(session,peer,own,token).open(fixture))
    }
    @Test fun roundtripAndCrossSessionRejection(){
        val sender=RelayCipher(session,peer,own,token);val receiver=RelayCipher(session,own,peer,token)
        val packet=ByteArray(1400){(it%251).toByte()};val frame=sender.seal(packet)
        assertArrayEquals(packet,receiver.open(frame));assertNull(receiver.open(frame))
        assertNull(RelayCipher("44444444-4444-4444-8444-444444444444",own,peer,token).open(frame))
    }
    @Test fun platformCryptoHasKnownHmacAndAesPadding(){
        val h=Crypto.hmac(ByteArray(20){0x0b},"Hi ".toByteArray(),"There".toByteArray())
        assertArrayEquals(unhex("b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7"),h)
        val key=ByteArray(32){it.toByte()};val iv=ByteArray(16){(it+2).toByte()};val plain="native SNV2".toByteArray()
        val encrypted=Crypto.aes(key,iv,plain,true);assertEquals(16,encrypted.size);assertArrayEquals(plain,Crypto.aes(key,iv,encrypted,false))
    }
}
